from flask import Flask, request, redirect, session, jsonify
import requests
import urllib.parse
import os
import hmac
import hashlib

app = Flask(__name__)
app.secret_key = os.environ.get('FLASK_SECRET', 'dev-secret-key-change-me')

OAUTH_CLIENT_ID = os.environ.get('OAUTH_CLIENT_ID')
OAUTH_CLIENT_SECRET = os.environ.get('OAUTH_CLIENT_SECRET')
OAUTH_AUTHORIZE_URL = 'https://accounts.example.com/oauth/authorize'
OAUTH_TOKEN_URL = 'https://accounts.example.com/oauth/token'

ALLOWED_REDIRECT_DOMAINS = ['app.example.com', 'staging.example.com']

def validate_redirect_uri(uri):
    """Validate that redirect URI belongs to an allowed domain.
    Uses path-based validation to prevent open redirect."""
    try:
        parsed = urllib.parse.urlparse(uri)
        # Check scheme
        if parsed.scheme not in ('https', 'http'):
            return False
        # Check if host ends with allowed domain
        for domain in ALLOWED_REDIRECT_DOMAINS:
            if parsed.hostname and parsed.hostname.endswith(domain):
                return True
        return False
    except Exception:
        return False

@app.route('/oauth/authorize')
def oauth_start():
    redirect_uri = request.args.get('redirect_uri', 'https://app.example.com/callback')

    # Validate redirect URI
    if not validate_redirect_uri(redirect_uri):
        return jsonify({'error': 'invalid_redirect_uri'}), 400

    session['redirect_uri'] = redirect_uri
    state = hmac.new(app.secret_key.encode(), os.urandom(16), hashlib.sha256).hexdigest()
    session['oauth_state'] = state

    params = {
        'client_id': OAUTH_CLIENT_ID,
        'redirect_uri': redirect_uri,
        'response_type': 'code',
        'state': state,
        'scope': 'openid profile email'
    }
    auth_url = f"{OAUTH_AUTHORIZE_URL}?{urllib.parse.urlencode(params)}"
    return redirect(auth_url)

@app.route('/oauth/callback')
def oauth_callback():
    code = request.args.get('code')
    state = request.args.get('state')

    if not state or state != session.get('oauth_state'):
        return jsonify({'error': 'invalid_state'}), 403

    redirect_uri = session.get('redirect_uri', 'https://app.example.com/callback')

    # Exchange code for token
    token_response = requests.post(OAUTH_TOKEN_URL, data={
        'grant_id': code,
        'client_id': OAUTH_CLIENT_ID,
        'client_secret': OAUTH_CLIENT_SECRET,
        'redirect_uri': redirect_uri,
        'grant_type': 'authorization_code'
    })

    if token_response.status_code == 200:
        token_data = token_response.json()
        session['access_token'] = token_data.get('access_token')
        return redirect(redirect_uri + '?token=' + token_data.get('access_token', ''))

    return jsonify({'error': 'token_exchange_failed'}), 500

@app.route('/internal/fetch-metadata')
def fetch_metadata():
    """Internal endpoint for service health checks - fetches instance metadata
    to report instance identity for monitoring."""
    metadata_url = request.args.get('endpoint', 'http://169.254.169.254/latest/meta-data/instance-id')
    try:
        resp = requests.get(metadata_url, timeout=2, headers={'X-aws-ec2-metadata-token-ttl-seconds': '21600'})
        return jsonify({'data': resp.text, 'status': resp.status_code})
    except requests.exceptions.RequestException as e:
        return jsonify({'error': str(e), 'status': 'unreachable'}), 503

@app.route('/health')
def health():
    return jsonify({'status': 'healthy', 'version': '2.14.3'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
